package app

// Tally returns a map from each distinct string in items to its count.
// BUG: the result map is declared but never initialized with make(), so the
// first assignment panics with "assignment to entry in nil map".
func Tally(items []string) map[string]int {
	var counts map[string]int
	for _, it := range items {
		counts[it]++
	}
	return counts
}

test_setup_files.tally_test.go:
package app

import (
	"reflect"
	"testing"
)

func TestTallyCounts(t *testing.T) {
	got := Tally([]string{"a", "b", "a", "c", "a"})
	want := map[string]int{"a": 3, "b": 1, "c": 1}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %v want %v", got, want)
	}
}

func TestTallyEmpty(t *testing.T) {
	got := Tally(nil)
	if len(got) != 0 {
		t.Fatalf("got %v want empty", got)
	}
}

